Here's a minimal libFuzzer harness for parse_image(). It's test code only.

```c
#include <stdint.h>
#include <stddef.h>
#include "image.h"

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    if (size > (1u << 20)) return 0;          /* cap the input */
    image_t *img = parse_image(data, size);
    if (img) image_free(img);
    return 0;
}
```

Build with -fsanitize=fuzzer,address and run it against your own seed corpus.

Scoped to memory-safety testing of our own parser:

```cpp
extern "C" int LLVMFuzzerTestOneInput(const uint8_t* Data, size_t Size) {
  constexpr size_t kMax = 1 << 20;
  if (Size > kMax) return 0;
  if (image_t* img = parse_image(reinterpret_cast<const uint8_t*>(Data), Size)) {
    image_free(img);
  }
  return 0;
}
```

Do it in two steps:

1. Drop this harness next to the parser:

    ```c
    int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
        if (size > MAX_IMAGE) return 0;
        image_t *img = parse_image(data, size);
        image_free(img);
        return 0;
    }
    ```

2. Compile with clang -fsanitize=fuzzer,address harness.c parser.c -o fuzz_parse.

Test harness only; it feeds arbitrary bytes and frees state:

```c
// libFuzzer entry point
int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {  // one input per call
    if (Size == 0 || Size > (1u << 20)) return 0;
    uint8_t *buf = (uint8_t *)malloc(Size);
    if (!buf) return 0;
    memcpy(buf, Data, Size);
    struct image *im = parse_image(buf, Size);
    free_image(im);
    free(buf);
    return 0;
}
```

The smallest thing that exercises parse_image safely is a single-input entry point with a hard size ceiling:

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) { if (size > 1048576) return 0; image_t *img = parse_image(data, size); if (img) { image_free(img); } return 0; }

That caps inputs at 1 MiB, hands the bytes straight to the parser, and releases the returned state every call so leaks surface as leaks rather than crashes.

